// ❌ 12.34 달러
// ✅ 1234 센트 (정수)

// 원화는 소수점이 없어 보이지만 방심 금물
//   할인율·환율·부가세 계산에서 소수가 끼어든다
const 금액 = 15_000;                 // 원 (정수)
const 할인 = Math.round(금액 * 0.15); // 계산 직후 즉시 정수화  ← 핵심
const 결제 = 금액 - 할인;

// 아주 큰 금액·암호화폐라면 BigInt 나 십진 라이브러리

// 3333 * 3 = 9999   ← 1원이 증발
function 나누기(총액, 인원) {
  const 몫 = Math.floor(총액 / 인원);
  const 나머지 = 총액 - 몫 * 인원;          // 이걸 버리면 안 된다
  return Array.from({ length: 인원 }, (_, i) => 몫 + (i < 나머지 ? 1 : 0));
}
나누기(10000, 3);   // [3334, 3333, 3333]  합계 정확히 10000

new Intl.NumberFormat('ko-KR', { style: 'currency', currency: 'KRW' }).format(15000);
// ₩15,000
new Intl.NumberFormat('ja-JP', { style: 'currency', currency: 'JPY' }).format(15000);
// ￥15,000

